import pandas as pd
import matplotlib.pyplot as plt

# Load the CSV generated by ns-3
df = pd.read_csv("traffic_pattern.csv")

# Create the plot
plt.figure(figsize=(10, 5))
plt.plot(df["Time"], df["Requests"], color='blue', linewidth=1.5, marker='o', markersize=3)

# Formatting
plt.title("Client Traffic Pattern (Burst Profile)", fontsize=14, fontweight='bold')
plt.xlabel("Simulation Time (Seconds)", fontsize=12)
plt.ylabel("Requests per 100ms", fontsize=12)
plt.grid(True, linestyle='--', alpha=0.7)
plt.xlim(0, 10)

# Save the chart as an image
plt.tight_layout()
plt.savefig("traffic_pattern_chart.png", dpi=300)
print("Chart saved successfully as 'traffic_pattern_chart.png'")
